def cmp_semver(a, b):
    a = a.strip()
    b = b.strip()
    def parse(v):
        v = v.split('+')[0]
        if '-' in v:
            base, pre = v.split('-', 1)
        else:
            base, pre = v, ''
        major, minor, patch = map(int, base.split('.'))
        if pre:
            pre_list = []
            for part in pre.split('.'):
                if part.isdigit():
                    pre_list.append(int(part))
                else:
                    pre_list.append(part)
        else:
            pre_list = []
        return (major, minor, patch, pre_list)
    a_parsed = parse(a)
    b_parsed = parse(b)
    for m, n in zip(a_parsed[:3], b_parsed[:3]):
        if m < n:
            return -1
        if m > n:
            return 1
    a_pre = a_parsed[3]
    b_pre = b_parsed[3]
    if len(a_pre) == 0 and len(b_pre) == 0:
        return 0
    if len(a_pre) == 0:
        return 1
    if len(b_pre) == 0:
        return -1
    for i in range(min(len(a_pre), len(b_pre))):
        a_id = a_pre[i]
        b_id = b_pre[i]
        a_num = isinstance(a_id, int)
        b_num = isinstance(b_id, int)
        if a_num and b_num:
            if a_id < b_id:
                return -1
            if a_id > b_id:
                return 1
        elif not a_num and not b_num:
            if a_id < b_id:
                return -1
            if a_id > b_id:
                return 1
        else:
            if a_num:
                return -1
            else:
                return 1
    if len(a_pre) > len(b_pre):
        return 1
    if len(a_pre) < len(b_pre):
        return -1
    return 0
