    # Strip and separate the header field name from the value
    header = header.strip()
    if ':' in header:
        _, value = header.split(':', 1)
        value = value.strip()
    else:
        value = header

    # The unit is case‑insensitive and must be 'bytes'
    value = value.lower()
    if not value.startswith('bytes='):
        return None

    ranges_str = value[6:]          # remove the 'bytes=' prefix
    if not ranges_str:
        return None

    parts = ranges_str.split(',')
    result = []

    for part in parts:
        # No whitespace may appear inside a range spec
        if any(c.isspace() for c in part):
            return None
        if not part:
            return None

        r = _parse_one(part, size)
        if r is None:
            continue          # unsatisfiable – drop it
        result.append(r)

    return result if result else None


